package com.keqi.reminder;

import org.json.*;
import java.util.*;

public final class DomainTests {
    private static int checks=0;
    static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    public static void main(String[] args) throws Exception {
        check(Core.status("已截止").equals("unknown"),"deadline passed is not submitted");
        check(Core.status("已截止（未提交）").equals("pending"),"unsubmitted expired assignment remains pending");
        check(Core.status("已提交，待批阅").equals("done"),"submitted zero-grade or ungraded is done");
        check(Core.parseTime("10-15 18:00",null).at==null,"no fabricated year");
        check(Core.parseTime("2026-10-15",null).at==null,"no fabricated 23:59");
        check(Core.parseTime("2026-02-30 18:00",null).at==null,"invalid date rejected");
        check(Core.parseTime("2026-10-15 18:00",null).at.equals(Core.parseTime("2026-10-15T10:00:00Z",null).at),"China timezone consistent with UTC");
        check(Core.parseRangeEnd("12-20 18:00","01-05 18:00",2026).at.equals(Core.parseTime("2027-01-05 18:00",null).at),"explicit cross-year date range");
        long now=Core.parseTime("2026-10-08 22:00",null).at;
        check(Core.mostUrgent(now+3600000,now,new double[]{72,24,3})==3,"new urgent task only gets most urgent past threshold");
        check(Core.mostUrgent(now-1,now,new double[]{72,24,3})==-1,"no obsolete reminder");
        check(!Core.currentThreshold(now+2*3600000,now,new double[]{72,24,3},72),"a delayed three-day alarm does not burst alongside urgent alarms");
        check(Core.currentThreshold(now+2*3600000,now,new double[]{72,24,3},3),"current urgent alarm remains eligible");
        check(Core.quietEnd(Core.parseTime("2026-10-08 23:30",null).at,"07:00")==Core.parseTime("2026-10-09 07:00",null).at,"quiet replay uses next morning");
        check(Core.parseRangeEnd("2026年12月20日 18:00","01-05 18:00",null).at==Core.parseTime("2027-01-05 18:00",null).at.longValue(),"source year can resolve cross-year ending without guessing");
        check(Core.quiet(Core.parseTime("2026-10-08 23:30",null).at,"23:00","07:00"),"quiet hours before midnight");
        check(Core.quiet(Core.parseTime("2026-10-09 06:30",null).at,"23:00","07:00"),"quiet hours after midnight");
        check(!Core.quiet(now,"23:00","07:00"),"daytime reminders allowed");
        JSONObject course=new JSONObject().put("key","cx:1:2:3").put("title","同名课程");
        String html="<li data='https://mooc1.chaoxing.com/mooc-ans/mooc2/work/task?workId=123&amp;enc=a'><p class='overHidden2 fl'>练习</p><p class='status fl'>未提交</p></li>";
        JSONArray cx=Collectors.chaoxingList(html,course,"account1");check(cx.length()==1,"attribute order, single quotes and ampersands handled");
        JSONObject task=cx.getJSONObject(0);Collectors.chaoxingDetail(task,"<div>作答时间: 12-20 18:00 至 01-05 18:00</div>",2026);
        check(task.getLong("due")==Core.parseTime("2027-01-05 18:00",null).at,"course year applied to range");
        Collectors.chaoxingDetail(task,"<div>作答时间: 10-10 18:00 至 10-15 18:00</div>",null);
        check(task.isNull("due")&&task.getString("precision").equals("year_missing"),"unknown year stays visible but unscheduled");
        JSONObject otherCourse=new JSONObject().put("key","cx:1:4:5").put("title","同名课程");
        check(!Collectors.chaoxingList(html,otherCourse,"account1").getJSONObject(0).getString("id").equals(task.getString("id")),"same titles/classes do not merge");
        check(!Collectors.chaoxingList(html,course,"account2").getJSONObject(0).getString("id").equals(task.getString("id")),"accounts isolated");
        JSONArray listed=Collectors.chaoxingCourses("<a href='stucoursemiddle?courseid=1&amp;clazzid=2&amp;cpi=3'><span class='course-name' title='课程 A'>A</span></a><a href='stucoursemiddle?courseid=4&amp;clazzid=5&amp;cpi=6'><span class='course-name' title='课程 B'>B</span></a>");
        check(listed.length()==2&&listed.getJSONObject(1).getString("title").equals("课程 B"),"unescaped course offsets retain correct titles");
        Collectors.PageLinks links=Collectors.pageLinks("<div class='pagination'><a href='?page=2'>2</a><a href='https://evil.example/list?page=3'>3</a></div>","https://mooc1.chaoxing.com/list?page=1");
        check(links.urls.size()==1&&links.urls.get(0).endsWith("page=2"),"pagination stays on the same HTTPS endpoint");
        check(Collectors.pageLinks("<div class='pagination'><a href='javascript:go(2)'>下一页</a></div>","https://mooc1.chaoxing.com/list").unresolved,"unreadable pagination reported");
        JSONObject moocCourse=new JSONObject().put("key","m:1:2").put("title","数学").put("url","https://www.icourse163.org/learn/XX-1?tid=2");
        JSONObject homework=new JSONObject().put("id",11).put("name","单元作业").put("contentType",3).put("deadline",now+86400000).put("evaluateEnd",now+172800000).put("usedTryCount",1);
        JSONArray mooc=Collectors.moocTasks(new JSONObject().put("result",new JSONObject().put("homeworks",new JSONArray().put(homework))),moocCourse,"a");
        check(mooc.length()==2,"submit and peer review have separate deadlines");
        check(mooc.getJSONObject(0).getString("status").equals("done")&&mooc.getJSONObject(1).getString("status").equals("unknown"),"submitted work does not cancel peer review");
        check(!mooc.getJSONObject(0).getString("id").equals(mooc.getJSONObject(1).getString("id")),"phase identity separate");
        JSONObject noDate=new JSONObject().put("id",12).put("name","无截止作业").put("contentType",3);
        check(Collectors.moocTasks(new JSONObject().put("homeworks",new JSONArray().put(noDate)),moocCourse,"a").getJSONObject(0).isNull("due"),"deadline-less assessed work retained");
        JSONObject nested=new JSONObject().put("id",13).put("name","测验").put("contentType",2).put("test",new JSONObject().put("id",14).put("name","测验").put("type",2).put("deadline",now+86400000));
        check(Collectors.moocTasks(new JSONObject().put("quizs",new JSONArray().put(nested)),moocCourse,"a").length()==1,"nested test metadata does not duplicate a task");
        JSONObject zero=new JSONObject().put("id",15).put("name","测验").put("contentType",2).put("score",0).put("mark",0);
        check(Collectors.moocTasks(zero,moocCourse,"a").getJSONObject(0).getString("status").equals("unknown"),"default zero mark cannot prove submission");
        zero.put("submitStatus","未提交").put("studentScore",0);
        check(Collectors.moocTasks(zero,moocCourse,"a").getJSONObject(0).getString("status").equals("pending"),"explicit pending status takes precedence over a score field");
        zero.put("submitStatus","已提交");
        check(Collectors.moocTasks(zero,moocCourse,"a").getJSONObject(0).getString("status").equals("done"),"zero-score submitted work remains done");
        JSONObject resource=new JSONObject().put("id",16).put("name","作业解析视频").put("contentType",1);
        check(Collectors.moocTasks(resource,moocCourse,"a").length()==0,"resource title alone does not create an assessed task");
        JSONObject unidentified=new JSONObject().put("name","测验").put("contentType",2);
        check(Collectors.moocBatch(unidentified,moocCourse,"a").warnings.size()==1,"missing stable identity produces a coverage warning");
        String encodedHtml="<li data='https://mooc1.chaoxing.com/work?workId=8&amp;enc=a%2Bb+c'><p class='overHidden2'>作业</p></li>";
        check(Collectors.chaoxingList(encodedHtml,course,"a").getJSONObject(0).getString("sourceUrl").endsWith("enc=a%2Bb+c"),"signed detail query is not decoded twice");
        JSONArray selected=new JSONArray().put(new JSONObject().put("key","c1").put("enabled",false)).put(new JSONObject().put("key","c2").put("enabled",true));
        JSONArray found=new JSONArray().put(new JSONObject().put("key","c1").put("title","updated title").put("enabled",true)).put(new JSONObject().put("key","c3"));
        JSONArray merged=CourseSelection.merge(selected,found);
        check(!merged.getJSONObject(0).getBoolean("enabled")&&merged.getJSONObject(0).getString("title").equals("updated title"),"sync or reconnect updates metadata while preserving a hidden course");
        check(merged.length()==3&&merged.getJSONObject(1).getString("key").equals("c2"),"partial rediscovery preserves existing courses and choices");
        check(merged.getJSONObject(2).optBoolean("enabled",true),"new courses remain enabled by default");
        check(CourseSelection.merge(null,new JSONArray().put(new JSONObject().put("key","c1"))).getJSONObject(0).optBoolean("enabled",true),"fresh account does not inherit hidden choices from another account");
        JSONObject pending=new JSONObject().put("key","chaoxing:1:2:pending").put("platform","chaoxing").put("courseId","1").put("classId","2").put("cpi","").put("enabled",false);
        JSONObject completed=new JSONObject().put("key","chaoxing:1:2:3").put("platform","chaoxing").put("courseId","1").put("classId","2").put("cpi","3").put("title","已补齐的课程");
        JSONArray upgraded=CourseSelection.merge(new JSONArray().put(pending),new JSONArray().put(completed));
        check(upgraded.length()==1&&!upgraded.getJSONObject(0).getBoolean("enabled"),"Chaoxing homework metadata completion preserves the hidden choice without a duplicate course");
        check(upgraded.getJSONObject(0).getString("key").equals("chaoxing:1:2:pending")&&upgraded.getJSONObject(0).getString("cpi").equals("3"),"course switch identity stays stable when an enrollment gains CPI metadata");
        JSONObject anotherClass=new JSONObject(completed.toString()).put("key","chaoxing:1:4:5").put("classId","4").put("cpi","5");
        check(CourseSelection.merge(new JSONArray().put(pending),new JSONArray().put(anotherClass)).length()==2,"same course in different Chaoxing classes keeps independent choices");
        JSONObject coded=new JSONObject().put("key","chaoxing:255733792:2:3").put("platform","chaoxing").put("courseId","255733792").put("classId","2").put("title","课程 255733792").put("enabled",false);
        JSONObject named=new JSONObject(coded.toString()).put("title","形势与政策3");
        JSONArray repaired=CourseSelection.merge(new JSONArray().put(coded),new JSONArray().put(named));
        check(repaired.getJSONObject(0).getString("title").equals("形势与政策3")&&!repaired.getJSONObject(0).getBoolean("enabled"),"refresh repairs a saved code label while retaining the hidden course");
        JSONObject unnamed=new JSONObject(coded.toString()).put("title","课程名称待更新");
        check(CourseSelection.merge(repaired,new JSONArray().put(unnamed)).getJSONObject(0).getString("title").equals("形势与政策3"),"a temporarily missing course name cannot overwrite a previously verified name");
        JSONObject cachedTask=new JSONObject().put("id","cached-work").put("platform","chaoxing").put("courseKey",coded.getString("key")).put("courseTitle","课程 255733792").put("version",7).put("due",now).put("manualDue",now+1).put("localDone",true).put("snoozeUntil",now+2).put("lastSeen",now-100);
        JSONObject otherTask=new JSONObject(cachedTask.toString()).put("id","other-class").put("courseKey","another-class");
        String expectedTask=new JSONObject(cachedTask.toString()).put("courseTitle","形势与政策3").toString();
        JSONArray renamed=CourseSelection.refreshTaskTitles(new JSONArray().put(cachedTask).put(otherTask),repaired);
        check(renamed.length()==1&&renamed.getJSONObject(0).toString().equals(expectedTask),"course refresh renames cached homework without changing identity, reminder version, deadlines or local edits");
        check(otherTask.getString("courseTitle").equals("课程 255733792"),"name updates stay on the matching course enrollment");
        System.out.println("Passed "+checks+" domain/adapter checks.");
    }
}
